// ── patch ────────────────────────────────────────────────────────────────────

const units  = JSON.parse(fs.readFileSync(UNITS_PATH, "utf-8"));
let patched  = 0;
let skipped  = 0;

for (const [code, overview] of Object.entries(OVERVIEWS)) {
  // Handle the tab-suffixed duplicate key (FIT3204\t)
  const key = Object.keys(units).find((k) => k.trim() === code);
  if (!key) { console.warn(`  WARNING: ${code} not found in mock_units.json`); continue; }
  if (units[key].overview) { skipped++; continue; }
  units[key].overview = overview;
  patched++;
}

fs.writeFileSync(UNITS_PATH, JSON.stringify(units, null, 4));
console.log(`Done. Patched ${patched} units, skipped ${skipped} (already had overview).`);
console.log(`Next step: node scripts/index-mock-data.js`);
